from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

@given('the Speech Text Reader page is loaded')
def step_impl(context):
    # Initialize the WebDriver and load the test page
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    context.driver.maximize_window()
    time.sleep(1)  # Allow the page to fully load

@given('the text box with data-testid "text-box" is initially hidden')
def step_impl(context):
    # Verify that the text box is initially hidden
    text_box = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='text-box']")
    # Check if the text box has the 'show' class, which indicates visibility
    assert 'show' not in text_box.get_attribute('class'), "Expected the text box to be initially hidden"

@when('the user clicks the \'Toggle Text Box\' button with data-testid "toggle-button"')
def step_impl(context):
    # Click the toggle button to toggle the visibility of the text box
    toggle_button = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='toggle-button']"))
    )
    toggle_button.click()
    time.sleep(1)  # Allow time for the visibility change to take effect

@then('the text box with data-testid "text-box" should be visible')
def step_impl(context):
    # Verify that the text box is now visible
    text_box = WebDriverWait(context.driver, 10).until(
        EC.visibility_of_element_located((By.CSS_SELECTOR, "[data-testid='text-box']"))
    )
    assert text_box.is_displayed(), "Expected the text box to be visible"

# Teardown to close the browser after the test
def after_scenario(context, scenario):
    if hasattr(context, 'driver'):
        context.driver.quit()

from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

def is_collapsed(element):
    aria = element.get_attribute("aria-expanded")
    if aria is not None and aria.lower() == "false":
        return True

    class_attr = element.get_attribute("class") or ""
    class_list = class_attr.split()
    if "collapsed" in class_list:
        return True

    data_expanded = element.get_attribute("data-expanded")
    if data_expanded is not None and data_expanded.lower() == "false":
        return True

    style = element.get_attribute("style") or ""
    if "display: none" in style or "visibility: hidden" in style or "height: 0" in style:
        return True

    return not element.is_displayed()

def is_visible(element):
    return element.is_displayed()

@given('the Speech Text Reader page is loaded')
def step_given_page_loaded(context):
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    time.sleep(1)  # Allow the page to load completely

@given('the user clicks the \'Toggle Text Box\' button with data-testid "toggle-button"')
def step_when_user_clicks_toggle_button(context):
    toggle_button = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='toggle-button']"))
    )
    toggle_button.click()
    time.sleep(1)  # Allow time for the toggle action to take effect


@given('the text box with data-testid "text-box" is visible')
def step_given_text_box_visible(context):
    text_box = WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, "[data-testid='text-box']"))
    )
    assert is_visible(text_box), "Text box is not visible initially"

@when('the user clicks the \'Toggle Text Box\' button with data-testid "toggle-button"')
def step_when_user_clicks_toggle_button(context):
    toggle_button = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='toggle-button']"))
    )
    toggle_button.click()
    time.sleep(1)  # Allow time for the toggle action to take effect

@then('the text box with data-testid "text-box" should be hidden')
def step_then_text_box_hidden(context):
    text_box = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='text-box']")
    # 检查是否没有 'show' 类，表示文本框被隐藏
    assert 'show' not in text_box.get_attribute('class') or not text_box.is_displayed(), "Text box is not hidden"




def after_scenario(context, scenario):
    context.driver.quit()

from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

def is_collapsed(element):
    aria = element.get_attribute("aria-expanded")
    if aria is not None and aria.lower() == "false":
        return True

    class_attr = element.get_attribute("class") or ""
    class_list = class_attr.split()
    if "collapsed" in class_list:
        return True

    data_expanded = element.get_attribute("data-expanded")
    if data_expanded is not None and data_expanded.lower() == "false":
        return True

    style = element.get_attribute("style") or ""
    if "display: none" in style or "visibility: hidden" in style or "height: 0" in style:
        return True

    return not element.is_displayed()

def is_visible(element):
    return element.is_displayed()

@given('the Speech Text Reader page is loaded')
def step_given_page_is_loaded(context):
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    time.sleep(1)

@given('the text box with data-testid "text-box" is initially hidden')
def step_given_text_box_initially_hidden(context):
    text_box = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='text-box']")
    assert not text_box.is_displayed() or 'show' not in text_box.get_attribute('class'), "Text box should be initially hidden"

@when('the user rapidly clicks the \'Toggle Text Box\' button with data-testid "toggle-button" multiple times')
def step_when_user_rapidly_clicks_toggle_button(context):
    toggle_button = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='toggle-button']"))
    )
    for _ in range(5):  # Simulate rapid clicking
        toggle_button.click()
        time.sleep(0.2)  # Short delay to simulate rapid clicking

@then('the text box with data-testid "text-box" should eventually be visible or hidden based on the final click')
def step_then_text_box_visibility(context):
    text_box = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='text-box']")
    # Check if the text box is either visible or hidden
    assert is_visible(text_box) or is_collapsed(text_box), "Text box should be either visible or hidden"

def after_scenario(context, scenario):
    context.driver.quit()

