from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

@given("the Speech Text Reader page is loaded")
def step_given_page_is_loaded(context):
    # Initialize the WebDriver and load the test page
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    time.sleep(1)  # Allow the page to load completely

@when("the page is initialized")
def step_when_page_is_initialized(context):
    # Wait for the page elements to be interactable
    WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, "[data-testid='toggle-button']"))
    )
    time.sleep(1)

@when("the user clicks the 'Toggle Text Box' button with data-testid \"toggle-button\" to display the text box")
def step_when_user_clicks_toggle_button(context):
    # Ensure the toggle button is visible and not obstructed
    toggle_button = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='toggle-button']"))
    )
    context.driver.execute_script("arguments[0].scrollIntoView(true);", toggle_button)  # Scroll to the button if necessary
    toggle_button.click()
    time.sleep(1)  # Allow the text box to toggle its visibility

@then("the 'Choose Voice' dropdown with data-testid 'voice-select' should be populated with available voices from the Web Speech API")
def step_then_dropdown_is_populated(context):
    # Wait for the dropdown to be populated
    voice_select = WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, "[data-testid='voice-select']"))
    )
    options = voice_select.find_elements(By.TAG_NAME, "option")
    assert len(options) > 0, "The 'Choose Voice' dropdown is not populated with voices."
    time.sleep(1)

# Cleanup after the test
def after_scenario(context, scenario):
    if hasattr(context, 'driver'):
        context.driver.quit()

from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

def is_visible(element):
    return element.is_displayed()

@given("the Speech Text Reader page has fully loaded")
def step_given_page_loaded(context):
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, "[data-testid='toggle-button']"))
    )
    time.sleep(1)

@given("the user clicks the 'Toggle Text Box' button identified by data-testid=\"toggle-button\" to reveal the text box")
def step_given_toggle_text_box(context):
    toggle_button = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='toggle-button']"))
    )
    toggle_button.click()
    time.sleep(1)

@given("the 'Choose Voice' dropdown identified by data-testid=\"voice-select\" is populated with available voices")
def step_given_voice_dropdown_populated(context):
    voices_dropdown = WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, "[data-testid='voice-select']"))
    )
    assert is_visible(voices_dropdown), "Voice dropdown is not visible"
    options = voices_dropdown.find_elements(By.TAG_NAME, "option")
    assert len(options) > 0, "Voice dropdown is not populated"
    time.sleep(1)

@when("the user selects an option from the 'Choose Voice' dropdown (data-testid='voice-select') where the option text includes 'US'")
def step_when_select_voice(context):
    voices_dropdown = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='voice-select']"))
    )
    voices_dropdown.click()
    time.sleep(1)
    options = voices_dropdown.find_elements(By.TAG_NAME, "option")
    voice_found = False
    for option in options:
        if "US" in option.text:
            option.click()
            voice_found = True
            break
    assert voice_found, "Voice 'Google US English' not found in the dropdown"
    time.sleep(1)

@then("the system should set the voice containing 'US' as the active voice for speech synthesis")
def step_then_verify_active_voice(context):
    voices_dropdown = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='voice-select']")
    selected_option = voices_dropdown.find_element(By.CSS_SELECTOR, "option:checked")
    assert "US" in selected_option.text, f"Expected 'Google US English', but got '{selected_option.text}'"
    time.sleep(1)

# Teardown
def after_scenario(context, scenario):
    context.driver.quit()

from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

def is_expanded(element):
    aria = element.get_attribute("aria-expanded")
    if aria is not None:
        return aria == "true"

    class_list = element.get_attribute("class").split()
    if any(cls in class_list for cls in ["expanded", "open", "show"]):
        return True

    data_expanded = element.get_attribute("data-expanded")
    if data_expanded is not None:
        return data_expanded == "true"

    return element.is_displayed()

@given('the Speech Text Reader page has fully loaded')
def step_impl(context):
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    time.sleep(1)

@given('the user clicks the \'Toggle Text Box\' button identified by data-testid="toggle-button" to reveal the text box')
def step_impl(context):
    toggle_button = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='toggle-button']"))
    )
    toggle_button.click()
    time.sleep(1)

@given('the \'Choose Voice\' dropdown identified by data-testid="voice-select" is populated with available voices')
def step_impl(context):
    voices_select = WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, "[data-testid='voice-select']"))
    )
    options = voices_select.find_elements(By.TAG_NAME, "option")
    assert len(options) > 0, "No voices available in the dropdown"
    time.sleep(1)

@when('the user selects an option from the \'Choose Voice\' dropdown (data-testid=\'voice-select\') where the option text includes \'CN\'')
def step_impl(context):
    voices_select = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='voice-select']")
    options = voices_select.find_elements(By.TAG_NAME, "option")
    for option in options:
        if 'CN' in option.text:
            option.click()
            break
    time.sleep(1)

@then('the system should set the voice containing ‘CN’ as the active voice for speech synthesis')
def step_impl(context):
    selected_voice = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='voice-select']").get_attribute("value")
    selected_voice_text = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='voice-select'] option:checked").text
    assert 'CN' in selected_voice_text, f"Expected selected voice to contain 'CN', but got '{selected_voice_text}'"
    time.sleep(1)

def after_scenario(context, scenario):
    context.driver.quit()

