from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

def is_visible(element):
    return element.is_displayed()

@given("the Speech Text Reader page is loaded")
def step_given_page_loaded(context):
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, "[data-testid='toggle-button']"))
    )
    time.sleep(1)

@given('the user clicks the "Toggle Text Box" button with data-testid "toggle-button" to display the text box')
def step_given_click_toggle_button(context):
    toggle_button = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='toggle-button']"))
    )
    toggle_button.click()
    time.sleep(1)

@given('the user enters "Testing voice change" into the textarea with data-testid \'text-area\'')
def step_given_enter_text(context):
    text_area = WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, "[data-testid='text-area']"))
    )
    text_area.clear()
    text_area.send_keys("Testing voice change")
    time.sleep(1)

@given('the user selects a voice from the dropdown with data-testid \'voice-select\'')
def step_given_select_voice(context):
    voice_select = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='voice-select']"))
    )
    options = voice_select.find_elements(By.TAG_NAME, "option")
    if options:
        options[0].click()  # Select the first voice option
    time.sleep(1)

@given('the user changes the voice selection to another voice')
def step_given_change_voice(context):
    voice_select = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='voice-select']"))
    )
    options = voice_select.find_elements(By.TAG_NAME, "option")
    if len(options) > 1:
        options[1].click()  # Select the second voice option
    time.sleep(1)

@when('the user clicks the \'Read Text\' button with data-testid \'read-button\'')
def step_when_click_read_button(context):
    read_button = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='read-button']"))
    )
    read_button.click()
    time.sleep(1)

@then('the system should read aloud "Testing voice change" using the newly selected voice')
def step_then_validate_text_read(context):
    # Since speech synthesis is a browser feature, we cannot directly validate the audio output.
    # Instead, we can check if the text message is set correctly in the textarea.
    text_area = WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, "[data-testid='text-area']"))
    )
    assert "Testing voice change" in text_area.get_attribute("value"), "Text was not set correctly for reading."

    # Cleanup: Close the browser
    context.driver.quit()

from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

def is_visible(element):
    return element.is_displayed()

@given("the Speech Text Reader page is loaded")
def step_given_page_is_loaded(context):
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, "[data-testid='toggle-button']"))
    )
    time.sleep(1)

@given('the user clicks the "Toggle Text Box" button with data-testid "toggle-button" to display the text box')
def step_given_toggle_text_box(context):
    toggle_button = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='toggle-button']"))
    )
    toggle_button.click()
    time.sleep(1)

@given("the textarea with data-testid 'text-area' is empty")
def step_given_textarea_is_empty(context):
    textarea = WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, "[data-testid='text-area']"))
    )
    assert textarea.get_attribute("value") == "", "Expected textarea to be empty"
    time.sleep(1)

@given("the user selects a voice from the dropdown with data-testid 'voice-select'")
def step_given_select_voice(context):
    voice_select = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='voice-select']"))
    )
    options = voice_select.find_elements(By.TAG_NAME, "option")
    assert len(options) > 0, "Expected at least one voice option"
    options[0].click()  # Select the first voice option
    time.sleep(1)

@when("the user clicks the 'Read Text' button with data-testid 'read-button'")
def step_when_click_read_button(context):
    read_button = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='read-button']"))
    )
    read_button.click()
    time.sleep(1)

@then("the system should not read aloud any text")
def step_then_no_text_read_aloud(context):
    # Since we cannot directly verify speech synthesis output, we check that no text is set in the message object
    textarea = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='text-area']")
    assert textarea.get_attribute("value") == "", "Expected no text to be read aloud"
    time.sleep(1)

# Teardown
def after_scenario(context, scenario):
    context.driver.quit()

from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

def is_expanded(element):
    aria = element.get_attribute("aria-expanded")
    if aria is not None:
        return aria == "true"

    class_list = element.get_attribute("class").split()
    if any(cls in class_list for cls in ["expanded", "open", "show"]):
        return True

    data_expanded = element.get_attribute("data-expanded")
    if data_expanded is not None:
        return data_expanded == "true"

    return element.is_displayed()

@given("the webpage is loaded and all predefined phrase boxes are displayed in the main section")
def step_given_webpage_loaded(context):
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, "main .box"))
    )
    time.sleep(1)

@when("the user clicks on the box containing the text \"I'm Thirsty\"")
def step_when_user_clicks_thirsty_box(context):
    boxes = context.driver.find_elements(By.CSS_SELECTOR, "main .box")
    for box in boxes:
        if "I'm Thirsty" in box.text:
            box.click()
            time.sleep(1)
            break

@then("the system should read aloud the text \"I'm Thirsty\"")
def step_then_system_reads_text(context):
    # Assuming the text is read aloud, we can't verify audio output directly.
    # This step is a placeholder for audio verification.
    pass

@then("the box should visually highlight by adding the \"active\" class")
def step_then_box_highlighted(context):
    boxes = context.driver.find_elements(By.CSS_SELECTOR, "main .box")
    for box in boxes:
        if "I'm Thirsty" in box.text:
            assert "active" in box.get_attribute("class"), "Box is not highlighted"
            break

@then("the highlight should disappear after 800 milliseconds")
def step_then_highlight_disappears(context):
    time.sleep(0.8)
    boxes = context.driver.find_elements(By.CSS_SELECTOR, "main .box")
    for box in boxes:
        if "I'm Thirsty" in box.text:
            assert "active" not in box.get_attribute("class"), "Box highlight did not disappear"
            break

def after_scenario(context, scenario):
    context.driver.quit()

from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

def is_active(element):
    """Helper function to check if the box is visually highlighted."""
    class_list = element.get_attribute("class").split()
    return "active" in class_list

@given("the webpage is loaded and all predefined phrase boxes are displayed in the main section")
def step_given_webpage_loaded(context):
    context.driver = webdriver.Chrome()  # Initialize the WebDriver
    context.driver.get(f"file://index.html")  # Load the test page
    WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, "main .box"))
    )  # Wait for the predefined phrase boxes to be displayed

@when('the user clicks on the box containing the text "{text}"')
def step_when_user_clicks_box(context, text):
    boxes = context.driver.find_elements(By.CSS_SELECTOR, "main .box")
    target_box = None
    for box in boxes:
        box_text = box.text.strip()
        print(box_text)
        if text.strip().lower() in box_text.lower():
            target_box = box
            break
    assert target_box is not None, f"Box with text '{text}' not found"
    WebDriverWait(context.driver, 10).until(EC.element_to_be_clickable(target_box))
    target_box.click()  # Click the box

@then('the system should read aloud the text "{text}"')
def step_then_system_reads_text(context, text):
    # Validate that the specified text is set in the SpeechSynthesisUtterance
    pass

@then('the box should visually highlight by adding the "active" class')
def step_then_box_highlights(context):
    active_boxes = [box for box in context.driver.find_elements(By.CSS_SELECTOR, "main .box") if is_active(box)]
    assert len(active_boxes) > 0, "Expected at least one box to be visually highlighted"

@then('the highlight should disappear after 800 milliseconds')
def step_then_highlight_disappears(context):
    time.sleep(0.8)  # Wait for 800 milliseconds
    active_boxes = [box for box in context.driver.find_elements(By.CSS_SELECTOR, "main .box") if is_active(box)]
    assert len(active_boxes) == 0, "Expected the highlight to disappear"

# Teardown step to close the browser after the test
def after_scenario(context, scenario):
    context.driver.quit()

from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

def is_expanded(element):
    aria = element.get_attribute("aria-expanded")
    if aria is not None:
        return aria == "true"

    class_list = element.get_attribute("class").split()
    if any(cls in class_list for cls in ["expanded", "open", "show"]):
        return True

    data_expanded = element.get_attribute("data-expanded")
    if data_expanded is not None:
        return data_expanded == "true"

    return element.is_displayed()

@given('the webpage is loaded and all predefined phrase boxes are displayed in the main section')
def step_given_webpage_loaded(context):
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    time.sleep(1)  # Allow time for the page to load

@when('the user clicks on the box containing the text "I\'m Angry" three times in quick succession')
def step_when_user_clicks_angry_box(context):
    main_section = WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.TAG_NAME, "main"))
    )
    angry_box = WebDriverWait(main_section, 10).until(
        EC.element_to_be_clickable((By.XPATH, "//p[contains(text(), \"I'm Angry\")]/.."))
    )
    for _ in range(3):
        angry_box.click()
        time.sleep(0.1)  # Simulate quick succession clicks

@then('the system should read aloud the text "I\'m Angry" three times')
def step_then_system_reads_aloud(context):
    # This step would require integration with a speech synthesis verification tool
    # Placeholder for actual speech synthesis verification
    pass

@then('the box should visually highlight by adding the "active" class each time')
def step_then_box_highlights(context):
    angry_box = context.driver.find_element(By.XPATH, "//p[contains(text(), \"I'm Angry\")]/..")
    assert "active" in angry_box.get_attribute("class"), "The box should be highlighted with 'active' class"

@then('the highlight should disappear after 800 milliseconds for each click')
def step_then_highlight_disappears(context):
    angry_box = context.driver.find_element(By.XPATH, "//p[contains(text(), \"I'm Angry\")]/..")
    time.sleep(0.8)  # Wait for the highlight to disappear
    assert "active" not in angry_box.get_attribute("class"), "The 'active' class should be removed after 800ms"

def after_scenario(context, scenario):
    context.driver.quit()
